cards.solution:
function validasiJumlah(teks) {
  const n = Number(teks);
  if (teks.trim() === "" || !Number.isInteger(n) || n <= 0) return null;
  return n;
}
for (const t of ["3", "0", "2.5", "abc", ""]) {
  console.log(validasiJumlah(t));
}
